window.kbPageData["views/entry/k-f4ff2d748783ad1d"] = {"key":"entry/k-f4ff2d748783ad1d","state":{"route":"entry/k-f4ff2d748783ad1d"},"node":{"id":"k-f4ff2d748783ad1d","mode":"k","title":"结构性货币政策工具","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2024 B类 行测#8"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["finance"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["经济指标与宏观调控"],"资料类别":["非时政"]},"directorySummary":"结构性货币政策工具是中央银行用于引导金融资源流向经济重点领域和薄弱环节的政策工具，兼顾货币政策的总量功能和定向支持功能。","review":{"definition":"结构性货币政策工具是中央银行用于引导金融资源流向经济重点领域和薄弱环节的政策工具，兼顾货币政策的总量功能和定向支持功能。","explanation":"碳减排支持工具和普惠养老专项再贷款分别引导金融机构支持碳减排和普惠养老。题目把D项的小微贷款减息支持作为面向小微企业的定向信贷支持来理解。C项的地方政府专项债券属于政府举债融资工具，因其财政政策属性而入选。判断时要看政策实施主体和资金运作方式，资金有指定用途这一点不足以区分二者。","references":[],"evidence":"围绕支持普惠金融、绿色发展、科技创新等国民经济重点领域和薄弱环节","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"d38a8ce0241af167","label":"结构性货币政策工具","topic":"经济指标与宏观调控","category":"非时政","text":"8.结构性货币政策工具\n我国的结构性货币政策工具是人民银行引导金融机构信贷投向，发挥精准滴灌、杠杆撬\n动作用的工具，通过提供再贷款或资金激励的方式，支持金融机构加大对特定领域和行业的\n信贷投放，降低企业融资成本。","source":{"doc":"6cbfb01fe723bba64b75","first":24,"last":24,"page":24,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"江苏 2024 B类 行测#8":{"paper":"江苏 2024 B类 行测","n":8,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",2],"asrc":["8dd171daee6fc74e9718.pdf",3],"card":"968e299dd64b8fead5bdeab6","links":[{"id":"k-f4ff2d748783ad1d","role":"直接考查","why":"结构性工具定向支持重点领域和薄弱环节，题中涉及碳减排支持工具、普惠养老专项再贷款和普惠小微贷款支持工具。"}]}},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-f4ff2d748783ad1d":[["江苏 2024 B类 行测#8"]]}};
